function clean(v) {
  return v === null || v === undefined ? '' : String(v).trim();
}
// Money is read from its decimal text and snapped to whole cents once, here.
// Everything downstream does integer-cent math and only divides by 100 at the end.
function toMoney(v) {
  const s = clean(v).replace(/[$,\s]/g, '');
  if (!/^-?\d+(\.\d+)?$/.test(s)) return null;
  return Math.round(Number(s) * 100) / 100;
}
function toInt(v) {
  const s = clean(v).replace(/[,\s]/g, '');
  if (!/^-?\d+$/.test(s)) return null;
  return Number(s);
}
function toIso(v) {
  const s = clean(v);
  if (!s) return null;
  const d = new Date(s);
  return Number.isNaN(d.getTime()) ? null : d.toISOString();
}

// Supplier A: JSON API. One item whose "products" array holds the rows.
const SUPPLIER = 'Supplier A';
const defaultCurrency = $('Config').first().json.currency;

const rows = [];
for (const item of $input.all()) {
  const products = Array.isArray(item.json.products) ? item.json.products : [];
  for (const product of products) rows.push(product);
}

return rows.map((p, index) => ({
  json: {
    sku: clean(p.sku).toUpperCase(),
    name: clean(p.title),
    brand: clean(p.brand),
    category: clean(p.category),
    cost: toMoney(p.unitCost),
    currency: clean(p.currency).toUpperCase() || defaultCurrency,
    stock: toInt(p.qtyAvailable),
    supplier: SUPPLIER,
    sourceUpdatedAt: toIso(p.updatedAt),
    sourceRow: index + 1,
  },
}));

// Offline stand-in for the Supplier B HTTP Request node.
// useSampleData = true  -> return the embedded copy of the sample feed.
// useSampleData = false -> pass the live HTTP response straight through.
const config = $('Config').first().json;
if (!config.useSampleData) {
  return $input.all();
}
const SAMPLE = {
  "data": "Item Code,Description,Manufacturer,Dept,Wholesale Price,Stock On Hand,Last Updated\n TB-750 ,Trail Bottle 750ml,HydraPeak,Hydration,5.95,40,2026-11-17\nHM-310,\"Hammock, Single\",Ridgeway,Shelter,21.00,10,2026-11-17\nST-410,Compact Stove,Emberline,Cooking,30.00,0,2026-11-12\nMG-055,Insulated Mug 350ml,HydraPeak,Hydration,0.00,75,2026-11-17\nSB-640,\"Sleeping Bag, 3-Season\",Ridgeway,Sleep,$54.90,18,2026-11-16\nPD-220,Sleeping Pad,Ridgeway,Sleep,27.25,-3,2026-11-17\nWF-077,Water Filter,HydraPeak,Hydration,18.60,33,2026-11-17\nRP-150,\"Paracord 15m \"\"Type III\"\"\",Ridgeway,Accessories,3.10,410,2026-11-10\nFK-018,Titanium Spork,Emberline,Cooking,2.50,90,2026-11-17\nDB-330,Dry Bag 30L,Ridgeway,Accessories,8.45,\"1,057\",2026-11-17\n"
};
return [{ json: SAMPLE }];

